cd /opt/nxeon && node -e '
import("./scripts/blog-seed-lib.mjs").then(async (m)=>{
  const rows = await m.db.blogPost.findMany({ where: { tags: { has: "seobatch" } }, select: { slug:true, body:true, title:true } });
  // build known slug set: all seobatch slugs + existing-slugs.tsv
  const fs = await import("fs");
  const tsv = fs.readFileSync("/tmp/claude-0/-root/4f329df3-66ee-49c8-a6c5-615ecf189efc/scratchpad/existing-slugs.tsv","utf8");
  const known = new Set();
  for (const line of tsv.split("\n")) { const c=line.split("\t"); if(c[2]) known.add(c[2].replace("/blog/","").trim()); }
  const allBatch = await m.db.blogPost.findMany({ select:{slug:true}});
  for (const r of allBatch) known.add(r.slug);
  let badLinks=0, scWarn=0, wcWarn=0;
  for (const r of rows) {
    const links=[...r.body.matchAll(/\]\(\/blog\/([a-z0-9-]+)\)/g)].map(x=>x[1]);
    for (const l of links) if(!known.has(l)){ console.log("BAD BLOG LINK in",r.slug,"->",l); badLinks++; }
    const sc=(r.body.match(/{{SCREENSHOT}}/g)||[]).length;
    if(sc<1||sc>2){ console.log("SCREENSHOT count",sc,"in",r.slug); scWarn++; }
    const wc=r.body.split(/\s+/).length;
    if(wc<1000||wc>1650){ console.log("WORDCOUNT",wc,"in",r.slug); wcWarn++; }
  }
  console.log("\nposts:",rows.length,"badBlogLinks:",badLinks,"screenshotWarns:",scWarn,"wordcountWarns:",wcWarn);
  await m.db.$disconnect();
});
' 2>&1

